// Conversation-derived reading layer. Included inside the explorer's closure.
let guideMode='overview',selectedQuestion='roles',searchText='',incidentId='preview',incidentStep=0;
let laneText=E.items.map(r=>'  '.repeat(r.depth)+r.text).join('\n'),laneOverride='auto';
const jump=(s,n=0,v='explain',q='')=>({scenario:s,step:n,view:v,question:q});
const qa=[
 {id:'roles',group:'Who does what',title:'Is the orchestrator different from the agent writing code?',
  answer:['The orchestrator is Python application code. The builder is a separate Claude Code process that reads files, edits code, and runs commands.','The orchestrator starts work, records lifecycle events, asks the Overseer for the next route, and invokes verification or repair. It does not approve every shell command the builder executes.'],
  detail:'“Agent” names a role in this codebase. It does not establish that the role is a persistent model session or a Claude subagent.',sources:[O(146,209),O(552,600),B(1398,1472)],jump:jump('todos',3),related:['overseer','nested','terminals']},
 {id:'overseer',group:'Who does what',title:'Is the Overseer an agent or code?',
  answer:['It is a Python routing module with an optional LLM call. It returns a structured decision; the orchestrator executes that decision.','Build requested, build completed, and verification failed use fixed rules without an Overseer model call. Interpreting a Bart message can use an LLM to choose Chat, Brainstorm, or Path.'],
  detail:'A fixed action does not imply zero model calls. Several other events still call the model and then force the fallback action. See the complete routing table below.',sources:[ref('agents/overseer.py',119,169)],jump:jump('bart',2),related:['overseer-matrix','orchestrator-rules','chat-brainstorm','path','rules','roles','bart']},
 {id:'rules',group:'Who does what',title:'What are the deterministic rules?',
  answer:['Build clicked → builder. Builder completed → verifier. Verification failed with fewer than two repairs → repair. Verification failed after two repairs → escalate to you. These decisions do not call an Overseer model.','Hard guards also constrain model-backed routing: a Bart message cannot directly dispatch Build or Verify; a verified result cannot start another build or verification. Invalid model responses fall back to fixed rules.'],
  detail:'These are examples. The complete Overseer table and orchestrator inventory are now appended to this question index. Fast/full selection is another deterministic rule, but it lives in build.py rather than the Overseer.',sources:[ref('agents/overseer.py',28,95),ref('agents/overseer.py',132,169)],related:['overseer-matrix','orchestrator-rules','fast-rules','error-prompts','overseer']},
 {id:'payload',group:'Sending TODOs',title:'What does the initial TODO payload look like? Is it JSON?',
  answer:['The browser sends a JSON operation containing the subgoal ID and selected TODO IDs. It does not put the entire Notes document into that HTTP request.','The server loads saved state and builds a Markdown prompt. Claude’s stream-json output is a third format: JSON events containing assistant text, tool activity, and result data.'],
  sources:[S(300,305),B(238,326),B(1525,1560)],jump:jump('todos',1,'payload'),related:['context','nested','claude-p']},
 {id:'nested',group:'Sending TODOs',title:'Do the three nested TODOs become three subagents?',
  answer:['In your original scenario, two top-level TODOs plus three nested TODOs are five stored rows, sent in one batch to one builder session. Nesting does not automatically launch subagents.','When a parent is selected, its children appear as indented instructions. Only the two selected parent units receive protocol IDs in the prompt; all five rows are tracked and verified.'],
  sources:[B(328,348),B(1737,1846)],jump:jump('todos',2,'payload'),related:['terminals','roles','fast-default']},
 {id:'terminals',group:'Sending TODOs',title:'Are the TODOs in the same terminal? What is a session?',
  answer:['One initial batch runs in one detached Claude Code process. Engelbart’s Terminal pane displays its output; no terminal window opens automatically.','A session is Claude’s conversation history. A process is one running program. A process can end and a new process can resume the same session with --resume. Those are different identities.'],
  sources:questions.processes.sources,jump:jump('todos',3,'payload'),related:['later-build','different-subgoal','nested']},
 {id:'claude-p',group:'Sending TODOs',title:'Is it using Claude -p? What can that do?',
  answer:['The default builder runs Claude Code with -p, a composed prompt, stream-json output, and acceptEdits permissions. It can read files, edit code, and run permitted commands and tools.','Engelbart closes the builder’s stdin. Follow-up work is handled through a new invocation or stop-and-resume, not text typed into an open input stream. The CLI itself supports more input modes than this launcher uses.'],
  sources:questions.claude.sources,jump:jump('todos',3,'payload'),related:['computer-use','terminals','bart']},
 {id:'computer-use',group:'Sending TODOs',title:'Can Claude -p use the computer?',
  answer:['Anthropic’s built-in computer-use feature requires an interactive session and is unavailable with -p. Permitted browser automation through an MCP tool or command is a separate capability.','Engelbart’s verifier has its own Playwright browser checks. That browser is separate from the builder’s tools. Ordinary Bart structured calls disable tools.'],
  sources:[ref('agents/artifacts.py',48,120),ref('providers.py',145,247)],links:questions.claude.links,related:['verification','claude-p','bart']},
 {id:'context',group:'Context & follow-up work',title:'Which Notes, goal context, and extra context reach the builder?',
  answer:['Full builds include a snapshot of the active goal tree and authored Notes, the focused goal, own prompt, Understanding, selected rows, and available acceptance, project resources, run instructions, attachments, and reader profile.','Quick builds omit the goal tree, Notes, own prompt, and Understanding. Neither lane automatically copies your original Claude chat or Bart transcript. A resource link is not automatically the full linked document.'],
  sources:questions.context.sources,jump:jump('todos',2,'context'),related:['new-notes','fast-rules','bart-context']},
 {id:'new-notes',group:'Context & follow-up work',title:'I add more Notes during a build. Does the builder receive them?',
  answer:['Saving the standard Notes tab updates local state. It does not send a message to, or refresh the prompt of, the running builder.','A later full build composes a fresh Notes snapshot. A later quick build omits those Notes. Joining rows through the backend also omits a fresh Notes snapshot: it resumes the existing conversation with a row-update message.','The standard Build control waits until this subgoal is no longer building/checking/fixing, and saving new rows is not an automatic queue. The legacy operation that redirects a building row with a note is a separate route.'],
  sources:[B(238,326),U(4640,4655),B(1993,2046),B(2325,2352)],jump:jump('todos',5,'context'),related:['same-subgoal-notes','queue-status','context','later-build','concurrency']},
 {id:'later-build',group:'Context & follow-up work',title:'Do the two later TODOs reuse the same session or start another?',
  answer:['After the earlier batch finishes, a full build starts a new Claude session with fresh context. A quick build can reuse a retained quick session for that subgoal, for up to eight uses if its transcript exists.','The initial full session is not automatically the retained quick session. In your original scenario, the first later quick batch starts a new session unless an older eligible quick session already exists.'],
  sources:[B(2057,2176)],jump:jump('todos',8,'payload'),related:['new-notes','terminals','fast-default']},
 {id:'different-subgoal',group:'Context & follow-up work',title:'What if the new TODO belongs to a different subgoal?',
  answer:['It gets a separate build record and builder session. The standard UI can allow it to run while the first subgoal is still busy.','Different subgoals can resolve to the same project directory. There is no automatic worktree isolation or shared-directory build lock, so their edits and local processes can interfere.'],
  sources:[A(686,717),ref('web/goal/store.js',116,139),B(2072,2176)],jump:jump('todos',5),related:['concurrency','preview-cause','terminals']},
 {id:'concurrency',group:'Context & follow-up work',title:'Can I send more TODOs before the previous ones finish?',
  answer:['You can save new TODOs and Notes while work runs. The standard Build control blocks dispatch on the same subgoal while it is building, checking, or fixing. New rows wait.','The backend separately supports joining rows to a running build by stopping its process and starting another with --resume. The standard UI guard prevents that path. Another subgoal can run concurrently.'],
  sources:questions.concurrency.sources,jump:jump('todos',5),related:['different-subgoal','bart-during-build','new-notes']},
 {id:'fast-default',group:'Fast/full & estimates',title:'Does the standard workspace use fast or full?',
  answer:['Both. The standard workspace lets a deterministic heuristic choose automatically unless a request or setting forces a lane.','Your hypothetical first batch has five rows, including the children, so it chooses full. The actual screenshot’s seven-row batch was also recorded with quick: false. The later two example UI TODOs qualify for quick.'],
  sources:[O(492,511),B(2057,2069)],jump:jump('todos',8),related:['fast-rules','context','nested']},
 {id:'fast-rules',group:'Fast/full & estimates',title:'Exactly what determines fast versus full?',
  answer:['The rule reads the expanded row count and literal TODO wording. One row must be 1–300 characters. Two or three rows must each be 1–500 characters and contain a recognized bounded-change word. Four or more rows choose full.','Every row must avoid risk keywords and vague commands such as “fix it.” There is no model judgment of difficulty; Notes and actual repository complexity are not inputs.'],
  detail:'Recognized bounded words include button, label(s), dropdown, slider, layout, render, display, timeline, checkbox, input, CSS, HTML, and local/prepared/synthetic dataset. Risk matches include auth, database, dependencies, migration, refactor, architecture, research, explore, investigate, delete, and deployment. The source below contains the full patterns. Request quick=true/false overrides selection; otherwise HC_BUILD_LANE=quick|full can override the heuristic.',
  sources:[B(2057,2069),O(492,500),U(850,877)],widget:'lane',related:['fast-default','context','time-estimates']},
 {id:'time-estimates',group:'Fast/full & estimates',title:'How is time estimated?',
  answer:['The builder is asked to emit an estimate before its first tool call. If a full build has not supplied one after 15 seconds, Engelbart falls back to median time per row from earlier recorded runs.','With no samples, it assumes four minutes per row: twenty minutes for your first five-row batch. The same run ETA appears under its rows. Quick builds do not receive this fallback.'],
  detail:'The countdown covers the current build. It is not a calibrated guarantee and does not comprehensively cover subsequent verification, repairs, or later requests.',sources:questions.estimates.sources,jump:jump('todos',4,'payload'),related:['token-estimates','verification','fast-rules']},
 {id:'token-estimates',group:'Fast/full & estimates',title:'How are tokens estimated and counted?',
  answer:['The model can supply an estimate. The full-build fallback uses recorded median cost per row; with no samples it assumes 30,000 tokens per row plus a rough context-size estimate. Five rows therefore yield about 150,000 tokens plus context.','Actual recorded usage sums input, output, cache creation, and cache reads. It is not simply the length of your TODO prompt, and the estimate is not a spending cap.'],
  sources:questions.estimates.sources,jump:jump('todos',4),related:['time-estimates','payload','context']},
 {id:'output',group:'Completion & verification',title:'What is the output once the TODOs are done?',
  answer:['The requested project changes, plus stored row states, build records, usage, activity, and verification evidence. Web work may also have a runnable preview.','There is no guaranteed deployment, PR, ZIP, or single final report. Rows added after the batch was dispatched are not completed by that earlier batch.'],
  sources:questions.output.sources,jump:jump('todos',7),related:['done','verification','preview-coupling']},
 {id:'done',group:'Completion & verification',title:'What is the difference between built, checked, and done?',
  answer:['A clean builder exit can mark remaining building rows done, even without explicit DONE markers. That is a completion claim. The orchestrator then asks the verifier to check all selected rows.','During checking or repair, the displayed lifecycle can override those stored done flags. The code does not cleanly separate “implementation finished,” “verification blocked,” and “verification passed.”'],
  sources:[B(1737,1846),U(604,655)],jump:jump('todos',6),related:['verification','preview-coupling','error-prompts']},
 {id:'verification',group:'Completion & verification',title:'What is verification?',
  answer:['It checks the builder’s output against saved acceptance criteria. It checks row/run state, preview availability, browser-observable results, and file properties.','Browser checks can find text and controls, inspect input values and layout, and perform specified click/fill steps. File checks can test existence, nonempty content, or expected text. An LLM judges collected evidence when the declarative checks are not considered complete.'],
  sources:[ref('agents/verifier.py',49,126),ref('agents/artifacts.py',48,186)],jump:jump('todos',7),related:['criteria','preview-coupling','done']},
 {id:'criteria',group:'Completion & verification',title:'What exactly does passing verification establish?',
  answer:['Only what the saved acceptance criteria and checks establish. Before a build, acceptance is generated if usable saved criteria are missing; it can still be incomplete or wrong.','In your real run, one check looked for a visible button named exactly “Delete.” That is weaker than proving deletion works. Testing deletion requires the relevant action and expected state change; persistence requires a further reload check.'],
  sources:[ref('agents/acceptance.py',65,158),ref('agents/artifacts.py',65,118)],related:['verification','error-prompts','output']},
 {id:'preview-coupling',group:'Completion & verification',title:'Must TODO completion communicate with live preview logic?',
  answer:['For UI TODOs to reach verified completion, the default workflow depends on a working preview. The builder finishes first; the verifier, rather than the builder, opens the preview.','File-only work can pass without a preview. However, the current artifact verifier also inspects a preview whenever a URL exists, even without web checks. That creates extra coupling.'],
  detail:'The correct interpretation of connection refused is “could not check,” not evidence that a feature failed. The current implementation routes that condition through the generic failure path.',sources:[ref('agents/artifacts.py',123,171),ref('agents/verifier.py',85,115)],related:['done','preview-cause','verification']},
 {id:'error-prompts',group:'The failures you showed',title:'Why are technical errors displayed as questions under every TODO?',
  answer:['The escalation emits a readable chat.needs_human question, then verify.escalated with the raw failure reason. The display projection takes the later event and overwrites the readable question with that reason.','Each TODO in the batch falls back to the same phase.reason and renders a Reply/Send form. One batch-level browser error therefore appears as many supposed questions.'],
  sources:[O(469,488),U(604,655),ref('web/goal/components/todos.js',62,107)],incident:'preview',related:['preview-cause','fixes','bart-loop']},
 {id:'preview-cause',group:'The failures you showed',title:'Why did the preview stop, and why wasn’t it recovered?',
  answer:['The builder ran pkill -f "goal_page.py" while restarting its own test server on port 8879. The workspace preview on port 8877 used the same script. The broad kill is the strongest supported cause of the shutdown; a PID-specific termination record is unavailable.','The verifier only calls ensure_preview when a URL is missing. A stopped server retains its URL, and the following guards omit the finished state. The dead URL therefore reaches browser inspection.'],
  detail:'The first part is an inference from the recorded command, matching server profile, and timing. The readiness bug is directly visible in the installed source.',sources:[ref('agents/verifier.py',85,115),ref('agents/runtime.py',164,199),ref('preview.py',648,739)],incident:'preview',related:['fixes','preview-coupling','different-subgoal']},
 {id:'fixes',group:'The failures you showed',title:'What causes these issues, and how should they be fixed?',
  answer:['There are four separate failure mechanisms: broad process cleanup, stale-URL readiness checks, treating unavailable verification as a code defect, and rendering one diagnostic as many questions.','The corresponding fixes are process ownership, health-based recovery, distinct acceptance-failed versus verification-blocked outcomes, and one batch-level message with separate diagnostics and optional human questions. These are proposed changes, not fixes applied to Engelbart.'],
  sources:[ref('agents/verifier.py',85,115),ref('agents/overseer.py',82,92),U(604,655),ref('web/goal/components/todos.js',62,107)],incident:'preview',related:['preview-cause','bart-loop','done']},
 {id:'bart',group:'Messaging Bart',title:'What currently happens when I send a message to Bart?',
  answer:['The browser sends this subgoal’s retained text conversation as JSON. The server reconstructs context and first checks whether it is handling an answer to a pending build question.','For an ordinary message, the Overseer selects Chat, Brainstorm, or Path; the responder makes a separate structured model call. Under the audited defaults these use Opus, low effort, with tools and Claude-session persistence disabled. The page then renders and saves the response.'],
  detail:'A typical ordinary turn has two model calls; context condensation or a bounded discovery pass can add calls. It does not send a message into the running builder.',sources:[O(214,286),ref('providers.py',145,247)],jump:jump('bart',0),related:['bart-context','bart-history','bart-loop']},
 {id:'bart-context',group:'Messaging Bart',title:'What Notes and context does Bart receive?',
  answer:['Different roles receive different context. The Overseer sees assembled state including the current run, compact plan, and bounded parent-goal Notes. Ordinary Chat gets a thinner digest, resources, focus titles, durable facts, activity, and text conversation.','Selected-subgoal Notes are absent from the ordinary compact digest. Chat does not automatically receive the richer router state. Its optional repository discovery is bounded, not a general coding-agent search.'],
  sources:questions.bartcontext.sources,jump:jump('bart',1,'context'),related:['context','bart-history','bart-loop']},
 {id:'bart-history',group:'Messaging Bart',title:'Does Bart have a persistent session and remember the whole chat?',
  answer:['The application stores a separate conversation for each subgoal and reconstructs model prompts. Each ordinary Claude call uses --no-session-persistence; there is no persistent Bart terminal session.','Stored chat is bounded to 200 messages and 4,000 characters per message. The request filters out proposal and lifecycle messages. Clearing visible chat does not clear the separate agent context or event history.'],
  sources:[S(231,253),U(711,744),ref('chat_state.py',1881,2008),ref('agents/communication.py',97,100)],jump:jump('bart',5),related:['bart-context','bart-loop','terminals']},
 {id:'bart-during-build',group:'Messaging Bart',title:'Can I talk to Bart while a TODO is running?',
  answer:['An ordinary Bart message is a separate conversation; it does not automatically steer the running builder. A pending builder question has a special answer path that can resume or cancel that build.','That special path is currently too broad: an unrelated question can be treated only as a failed attempt to answer the pending build question, then receive the old question again.'],
  sources:[O(214,286)],jump:jump('bart',2),related:['bart-loop','concurrency','bart']},
 {id:'bart-loop',group:'The failures you showed',title:'Why did “how does Bart work” get the previous failure message again?',
  answer:['The earlier escalation left a pending question with resume=build. The orchestrator intercepted your new message before ordinary Overseer routing and asked Chat whether it authorized resuming or cancelling.','If the result has an unresolved need or is neither resume nor cancel, the code discards the generated response and returns the saved question verbatim. This is why the screenshot repeats the exact work-update text as a Bart reply.'],
  detail:'The fix is to distinguish an answer to the pending decision, a question about the blocker, and an unrelated conversation. Only the first should change whether the build continues.',sources:[O(229,286),ref('agents/communication.py',97,100)],incident:'bart',related:['bart-during-build','error-prompts','overseer']}
];
