function guideSources(sources,provenance=''){
 return '<details class="evidence-disclosure"><summary>Code & evidence · '+sources.length+' source excerpts</summary>'+(provenance?'<p class="evidence-provenance">'+esc(provenance)+'</p>':'')+sources.map(s=>{
  const raw=E.sources[s.file];const code=raw?raw.text.split('\n').slice(s.start-1,s.end).map((t,i)=>String(i+s.start).padStart(4)+'  '+t).join('\n'):'Source unavailable';
  return '<details class="evidence-source"><summary>'+esc(s.file.replace('trajectory/',''))+':'+s.start+'–'+s.end+'</summary><pre>'+esc(code)+'</pre><p class="evidence-provenance">Installed 0.20.4 · SHA-256 '+esc(raw?.sha256||'')+'</p></details>';
 }).join('')+'</details>';
}
function qButton(id,label){return '<button data-qa="'+id+'">'+esc(label||qaById[id].title)+'</button>'}
function guideFooter(){return '<div class="guide-scope">Inspected September 13, 2026 · installed Engelbart 0.20.4 · default agents + headless workflow. Question wording is consolidated from this conversation. The original traces use synthetic records; failure replays use curated observations from your logs and screenshots. Proposed fixes are not applied to Engelbart. This page runs no models, builds, retries, or account actions. <a href="README.md">Reproduce and inspect the evidence boundary</a>.</div>'}
function renderOverview(){
 $('guide-panel').innerHTML='<div class="guide-head"><div><p class="guide-kicker">The questions from this conversation, in one place</p><h2>Keep the boundaries in view.</h2><p class="guide-lead">'+qa.length+' answers, two build/chat walkthroughs, and both failures you showed. Read one answer, then open its trace when you need the mechanics.</p></div><button class="primary" data-guide="questions">Find a question</button></div>'+
 '<div class="orientation"><div><h3>Three distinctions explain most of the surprises</h3><dl class="boundary-list"><div><dt>A role is not necessarily a model.</dt><dd>The orchestrator is code. The Overseer is code with optional model routing. The builder is a separate Claude Code process.</dd></div><div><dt>Saved context is not necessarily sent context.</dt><dd>Notes can be saved while a build runs. That does not update its prompt, and a later quick build omits Notes.</dd></div><div><dt>Built is not the same as verified.</dt><dd>A builder can finish while verification is blocked. The current UI can turn that blocker into “Needs you.”</dd></div></dl></div><div class="reading-start"><h3>Start with the behavior that confused you</h3><p>The repeated Bart reply and the technical “questions” are connected: the same failed verification created the pending build question that intercepted your later message.</p><div class="guide-links"><button class="primary" data-incident="bart">Replay the repeated Bart reply</button><button data-incident="preview">Trace the preview failure</button></div><p class="small">Observed behavior, causes, and proposed fixes are separate in each replay.</p></div></div>'+
 '<h3>The TODO path · select a component</h3><div class="architecture-strip">'+[
  ['payload','Workspace','Browser + local API','Saves rows and sends their IDs.'],['roles','Orchestrator','Python code','Coordinates the lifecycle; calls the Overseer.'],['overseer','Overseer','Code + optional LLM','Selects the next action under fixed rules.'],['claude-p','Builder','Claude Code process','Receives a batch, edits files, runs tools.'],['verification','Verifier','Checks + optional LLM','Inspects evidence; returns an outcome.']
 ].map(([q,n,t,d])=>'<button data-qa="'+q+'"><strong>'+n+'</strong><span class="role-type">'+t+'</span><small>'+d+'</small></button>').join('')+'</div><p class="small">The verifier returns to the orchestrator: finish, repair, or escalate. The Overseer does not review every builder command.</p>'+
 '<div class="story-list"><div class="story-entry"><span class="index">1</span><div><h3>Your original TODO scenario</h3><p>Notes → two roots + three children → Build all → new Notes + two more TODOs.</p></div><button data-trace="todos" data-trace-step="0">Walk through the batch</button></div><div class="story-entry"><span class="index">2</span><div><h3>You send a message to Bart</h3><p>Conversation → context → routing → responder → saved reply.</p></div><button data-trace="bart" data-trace-step="0">Walk through a message</button></div><div class="story-entry"><span class="index">3</span><div><h3>The two failures connect those paths</h3><p>Preview unavailable → escalation → repeated TODO prompts → pending-question trap.</p></div><button data-incident="preview">Follow the failure chain</button></div></div>'+
 '<h3>Jump to a specific uncertainty</h3><div class="reading-paths">'+qButton('fast-rules','Try the fast/full rule')+qButton('context','See what Notes are sent')+qButton('rules','Which decisions are just code?')+qButton('preview-coupling','Why does completion depend on preview?')+'</div><div style="height:28px"></div>'+guideFooter();
}
function filteredQuestions(){const term=searchText.trim().toLowerCase();return qa.filter(q=>!term||[q.title,q.group,...q.answer,q.detail||'',q.id].join(' ').toLowerCase().includes(term))}
function renderQuestionList(){const found=filteredQuestions();$('qa-count').textContent=found.length+' of '+qa.length+' questions';$('qa-results').innerHTML=found.length?groups.map(group=>{const rows=found.filter(q=>q.group===group);return rows.length?'<h3 class="qa-group">'+esc(group)+'</h3>'+rows.map(q=>'<button class="qa-row" data-qa="'+q.id+'" aria-current="'+(q.id===selectedQuestion)+'">'+esc(q.title)+'</button>').join(''):''}).join(''):'<p class="small">No matching question. Try “notes,” “preview,” or “Bart.”</p>'}
function renderQuestionArticle(){
 const q=qaById[selectedQuestion]||qa[0],i=qa.indexOf(q);
 $('qa-article').innerHTML='<p class="guide-kicker">'+esc(q.group)+'</p><h2>'+esc(q.title)+'</h2><div class="qa-answer">'+q.answer.map(p=>'<p>'+esc(p)+'</p>').join('')+'</div>'+(q.detail?'<p class="qa-detail">'+esc(q.detail)+'</p>':'')+
 (q.widget==='lane'?laneWidget():policyWidget(q.widget))+
 '<div class="guide-links">'+(q.jump?'<button class="primary" data-qa-trace="'+q.id+'">Open the relevant trace</button>':'')+(q.incident?'<button class="primary" data-incident="'+q.incident+'">Replay this failure</button>':'')+'</div>'+
 guideSources(q.sources)+(q.links?'<p class="small">Official capability references, checked September 13: '+q.links.map(([t,u])=>'<a href="'+u+'" target="_blank" rel="noreferrer">'+esc(t)+'</a>').join(' · ')+'</p>':'')+
 '<h3>Connected questions</h3><div class="guide-links">'+(q.related||[]).map(id=>qButton(id)).join('')+'</div><div class="question-neighbors"><button data-qa="'+(qa[i-1]?.id||q.id)+'" '+(i===0?'disabled':'')+'>← Previous question</button><button data-qa="'+(qa[i+1]?.id||q.id)+'" '+(i===qa.length-1?'disabled':'')+'>Next question →</button></div>';
 if(q.widget==='lane')renderLaneResult();
 if(q.widget==='policy')renderPolicyResult();
}
function renderQuestions(){
 $('guide-panel').innerHTML='<div class="guide-head"><div><h2>Your questions</h2><p class="guide-lead">One answer at a time. Search by your wording; related questions and traces preserve the connections.</p></div><button data-guide="overview">Back to the overview</button></div><div class="qa-layout"><aside class="qa-sidebar" aria-label="Question index"><label for="qa-search">Search this conversation</label><input class="qa-search" id="qa-search" type="search" placeholder="Notes, fast, preview, tokens…" value="'+esc(searchText)+'"><div class="qa-count" id="qa-count" role="status"></div><div class="qa-results" id="qa-results"></div></aside><article class="qa-article" id="qa-article" aria-live="polite"></article></div><div style="height:32px"></div>'+guideFooter();
 renderQuestionList();renderQuestionArticle();
}
// Python's \w/\b are Unicode-aware; JS's default \b is not. Preserve those
// boundaries and count code points so the local rule matches the Python probe.
const word='[\\p{L}\\p{N}_]';
const boundary='(?:(?<='+word+')(?!'+word+')|(?<!'+word+')(?='+word+'))';
const pythonRegex=pattern=>new RegExp(pattern.replace(/\\w/g,word).replace(/\\b/g,boundary),'iu');
const riskPattern=pythonRegex(E.lane_patterns.risky),boundedPattern=pythonRegex(E.lane_patterns.bounded);
function classifyLane(rows,override='auto'){
 const reasons=[];if(override!=='auto')return {quick:override==='quick',reasons:['Forced '+override+' lane; the count and wording heuristic is bypassed.']};
 if(rows.length<1||rows.length>3)return {quick:false,reasons:[rows.length+' expanded rows; automatic fast requires 1–3.']};
 rows.forEach((text,i)=>{const count=[...text].length,limit=rows.length===1?300:500,matched=text.match(riskPattern);
  if(count<1||count>limit)reasons.push('Row '+(i+1)+': '+count+' characters; allowed range is 1–'+limit+'.');
  if(matched)reasons.push('Row '+(i+1)+': risk keyword “'+matched[0]+'”.');
  if(/^(?:fix|do|finish|improve|change|build|make) (?:it|this|that)(?: better)?[.!]?$/i.test(text.trim()))reasons.push('Row '+(i+1)+': vague command.');
  if(rows.length>1&&!boundedPattern.test(text))reasons.push('Row '+(i+1)+': no recognized bounded-change keyword.');
 });
 return {quick:reasons.length===0,reasons:reasons.length?reasons:['All '+rows.length+' rows pass the size, wording, and risk checks.']};
}
const lanePresets={original:E.lane_cases.find(c=>c.id==='original').rows,later:E.lane_cases.find(c=>c.id==='later').rows,wording_full:E.lane_cases.find(c=>c.id==='wording_full').rows,wording_fast:E.lane_cases.find(c=>c.id==='wording_fast').rows,risky:E.lane_cases.find(c=>c.id==='risky').rows};
function laneWidget(){return '<section class="lane-box" aria-label="Fast versus full simulator"><h3>Try the actual selection rule</h3><p class="small">One TODO per line. Indentation illustrates children; every nonblank line counts as a row. This runs only a local replica of the heuristic and never starts a build.</p><div class="lane-presets"><button data-lane="original">Original five rows</button><button data-lane="later">Later two rows</button><button data-lane="wording_full">“Navigation item”</button><button data-lane="wording_fast">“Navigation label”</button><button data-lane="risky">Risk keyword</button></div><label for="lane-input">Edit the TODO wording</label><textarea id="lane-input" spellcheck="false">'+esc(laneText)+'</textarea><label for="lane-override">Selection mode in this example</label><select id="lane-override"><option value="auto" '+(laneOverride==='auto'?'selected':'')+'>Automatic (standard workspace default)</option><option value="quick" '+(laneOverride==='quick'?'selected':'')+'>Force quick</option><option value="full" '+(laneOverride==='full'?'selected':'')+'>Force full</option></select><div id="lane-result" class="lane-result" role="status" aria-live="polite"></div></section>'}
function renderLaneResult(){const rows=laneText.split('\n').map(t=>t.replace(/^\s*(?:[-*]\s+)?(?:\[[ xX]\]\s*)?/, '')).filter(t=>t.trim()),r=classifyLane(rows,laneOverride);$('lane-result').innerHTML='<strong>'+(r.quick?'Fast / quick':'Full')+'</strong><span class="small"> · '+rows.length+' rows</span><ul>'+r.reasons.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul><div class="fact">'+(r.quick?'This lane omits the goal tree and authored Notes from the newly composed prompt.':'This lane includes a fresh snapshot of the goal tree and authored Notes.')+'</div>'}
function replayMarkup(kind){if(kind==='todos')return '<div class="replay-ui"><div class="replay-title">Reconstruction of the shared error · two of seven affected rows</div>'+['Project goals should be read/write','Archiving goals'].map(t=>'<div class="replay-todo"><span class="needs">Needs you</span><strong>'+t+'</strong><div class="replay-error">'+esc(rawPreviewError)+'</div><div class="replay-answer">Reply… <span style="float:right">Send</span></div></div>').join('')+'</div>';return '<div class="replay-ui"><div class="replay-title">Reconstruction of your Bart screenshot</div>'+[['Bart · work update',oldQuestion],['You','how does bart work'],['Bart',oldQuestion]].map(([who,t])=>'<div class="replay-message '+(who==='You'?'user':'')+'"><span class="speaker">'+who+'</span><p>'+esc(t)+'</p></div>').join('')+'</div>'}
function renderIncidents(){const incident=incidents[incidentId],s=incident.steps[incidentStep];
 $('guide-panel').innerHTML='<div class="guide-head"><div><h2>What went wrong</h2><p class="guide-lead">Replay the actual evidence. Proposed fixes stay separate from the installed behavior.</p></div><button data-qa="'+incident.question+'">Read the short answer</button></div><div class="incident-tabs" aria-label="Choose a failure"><button data-incident="preview" aria-pressed="'+(incidentId==='preview')+'">Preview error → TODO questions</button><button data-incident="bart" aria-pressed="'+(incidentId==='bart')+'">Pending question → repeated Bart reply</button></div><h3 style="font-size:18px;margin:0 0 8px">'+incident.title+'</h3><p class="small">'+incident.subtitle+'</p><div class="incident-layout"><nav class="incident-timeline" aria-label="Failure timeline">'+incident.steps.map((t,i)=>'<button class="incident-stop" data-incident-step="'+i+'" aria-current="'+(i===incidentStep?'step':'false')+'"><span class="index">'+(i+1)+'</span><span><strong>'+t.title+'</strong><small>'+t.time+'</small></span></button>').join('')+'</nav><article class="incident-article" aria-live="polite"><span class="evidence-tag '+(s.inference?'inference':'')+'">'+s.label+'</span><h3>'+s.title+'</h3><p>'+esc(s.body)+'</p>'+(incidentId==='preview'&&incidentStep>=4?'<div class="state-grid"><div><span>Builder claim</span><strong>Done</strong></div><div><span>Verifier record</span><strong>Failed to inspect</strong></div><div><span>UI after escalation</span><strong>Needs you</strong></div></div>':'')+(s.replay?replayMarkup(s.replay):'')+'<details class="evidence-disclosure"><summary>Recorded fields / relevant branch</summary><div class="incident-record"><pre>'+esc(JSON.stringify(s.record,null,2))+'</pre></div><p class="evidence-provenance">Curated excerpt: '+esc(s.recordSource)+'. Field names may be condensed for readability; no new model response is fabricated.</p></details>'+guideSources(s.sources)+'<div class="incident-controls"><button data-incident-step="'+Math.max(0,incidentStep-1)+'" '+(incidentStep===0?'disabled':'')+'>← Previous event</button><button data-incident-step="'+Math.min(incident.steps.length-1,incidentStep+1)+'" '+(incidentStep===incident.steps.length-1?'disabled':'')+'>Next event →</button></div><details class="fix-disclosure"><summary>Proposed fixes · not implemented in Engelbart</summary><ol>'+incident.fixes.map(([t,d])=>'<li><strong>'+t+'.</strong> '+d+'</li>').join('')+'</ol><p><strong>Regression scenario:</strong> '+incident.test+'</p></details><div class="guide-links">'+qButton(incident.question,'Read the diagnosis')+(incidentId==='preview'?'<button data-incident="bart">Follow what happened in Bart</button>':'<button data-incident="preview">See where the pending question came from</button>')+'</div></article></div><div style="height:30px"></div>'+guideFooter();
}
function selectMode(mode){guideMode=mode;$('guide-panel').hidden=mode==='trace';$('scenario-panel').hidden=mode!=='trace';document.querySelectorAll('[data-guide][role=tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.guide===mode)));document.querySelectorAll('[data-scenario][role=tab]').forEach(b=>b.setAttribute('aria-selected',String(mode==='trace'&&b.dataset.scenario===scenario)));if(mode!=='trace')$('guide-panel').setAttribute('aria-labelledby','tab-'+mode)}
function scrollReading(id){$(id).scrollIntoView({block:'start',behavior:'instant'});}
function openQuestion(id){if(!qaById[id])id=qa[0].id;selectedQuestion=id;const was=guideMode==='questions';selectMode('questions');if(was&&$('qa-article')){renderQuestionList();renderQuestionArticle()}else renderQuestions();history.pushState(null,'','#question='+encodeURIComponent(id));scrollReading('qa-article');}
function openTrace(s,n=0,v='explain',q=''){scenario=s;step=n;view=v;question=q||null;sourceIndex=0;other=false;selectMode('trace');render();saveTraceLocation();scrollReading('scenario-panel');}
function saveTraceLocation(){if(guideMode!=='trace')return;const params=new URLSearchParams({trace:scenario,step:String(step),view});if(question)params.set('inspect',question);if(scenario==='bart')params.set('route',bartRoute);if(other)params.set('other','1');if(forceFull)params.set('full','1');history.replaceState(null,'','#'+params);}
function openIncident(id,n=0){incidentId=id;incidentStep=n;selectMode('incidents');renderIncidents();history.pushState(null,'','#incident='+id+'&step='+n)}
function openGuide(mode){selectMode(mode);if(mode==='overview')renderOverview();else if(mode==='questions')renderQuestions();else renderIncidents();history.pushState(null,'',mode==='questions'?'#question='+selectedQuestion:mode==='incidents'?'#incident='+incidentId+'&step='+incidentStep:'#overview');scrollReading('guide-panel');}
function readLocation(){const p=new URLSearchParams(location.hash.slice(1));
 if(p.has('question')){selectedQuestion=qaById[p.get('question')]?p.get('question'):qa[0].id;selectMode('questions');renderQuestions();}
 else if(p.has('incident')){incidentId=p.get('incident')==='bart'?'bart':'preview';incidentStep=Math.max(0,Math.min(incidents[incidentId].steps.length-1,parseInt(p.get('step'),10)||0));selectMode('incidents');renderIncidents();}
 else if(p.has('trace')){scenario=p.get('trace')==='bart'?'bart':'todos';bartRoute=['chat','brainstorm','path','answer'].includes(p.get('route'))?p.get('route'):'chat';step=Math.max(0,Math.min(steps().length-1,parseInt(p.get('step'),10)||0));view=['explain','payload','context','source'].includes(p.get('view'))?p.get('view'):'explain';question=questions[p.get('inspect')]?p.get('inspect'):null;other=p.get('other')==='1';forceFull=p.get('full')==='1';sourceIndex=0;selectMode('trace');render();}
 else{selectMode('overview');renderOverview();}
}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;
 if(b.dataset.guide)openGuide(b.dataset.guide);
 else if(b.dataset.qa)openQuestion(b.dataset.qa);
 else if(b.dataset.qaTrace){const q=qaById[b.dataset.qaTrace],j=q.jump;openTrace(j.scenario,j.step,j.view,j.question);}
 else if(b.dataset.trace)openTrace(b.dataset.trace,Number(b.dataset.traceStep||0));
 else if(b.dataset.incident)openIncident(b.dataset.incident);
 else if(b.dataset.incidentStep!==undefined)openIncident(incidentId,Number(b.dataset.incidentStep));
 else if(b.dataset.lane){laneText=lanePresets[b.dataset.lane].join('\n');laneOverride='auto';$('lane-input').value=laneText;$('lane-override').value='auto';renderLaneResult();}
});
document.addEventListener('input',event=>{if(event.target.id==='qa-search'){searchText=event.target.value;renderQuestionList();}else if(event.target.id==='lane-input'){laneText=event.target.value;renderLaneResult();}});
document.addEventListener('change',event=>{if(event.target.id==='lane-override'){laneOverride=event.target.value;renderLaneResult();}});
window.addEventListener('popstate',readLocation);window.addEventListener('hashchange',readLocation);
